*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:          #0f1117;
  --surface:     #1a1d27;
  --surface-2:   #22263a;
  --border:      #2e3350;
  --accent:      #7c6af7;
  --accent-dim:  #5548c8;
  --accent-glow: rgba(124, 106, 247, 0.18);
  --text:        #e8eaf6;
  --text-muted:  #8b90b8;
  --answer-bg:   #14172080;
  --radius:      12px;
  --transition:  220ms ease;
  --focus-ring:  0 0 0 3px var(--accent-glow), 0 0 0 2px var(--accent);
}

html { color-scheme: dark; }

body {
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  line-height: 1.6;
}

/* ── Skip link ────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; outline: 2px solid #fff; outline-offset: 2px; }

/* ── Header ───────────────────────────────────────────────── */
.site-header {
  text-align: center;
  padding: 3rem 1.5rem 2rem;
  background: linear-gradient(160deg, #16192680 0%, #0f111700 100%);
  border-bottom: 1px solid var(--border);
}
.header-icon { font-size: 3rem; display: block; margin-bottom: 0.5rem; }
.site-header h1 {
  font-size: clamp(1.8rem, 5vw, 2.8rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  background: linear-gradient(135deg, #a89ef9 0%, var(--accent) 60%, #4fc3f7 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.header-subtitle {
  margin-top: 0.5rem;
  color: var(--text-muted);
  font-size: 1.05rem;
}

/* ── Main content ─────────────────────────────────────────── */
main {
  max-width: 780px;
  margin: 0 auto;
  padding: 2.5rem 1.25rem 4rem;
}

/* ── FAQ item wrapper ─────────────────────────────────────── */
.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-bottom: 0.85rem;
  overflow: hidden;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.example:hover {
  border-color: var(--accent-dim);
  box-shadow: 0 2px 16px var(--accent-glow);
}
.example.is-open {
  border-color: var(--accent);
  box-shadow: 0 4px 24px var(--accent-glow);
}

/* ── Trigger button ───────────────────────────────────────── */
.faq-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  padding: 1.1rem 1.4rem;
  background: transparent;
  border: none;
  color: var(--text);
  font-size: 1.05rem;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  border-radius: var(--radius);
  transition: background var(--transition), color var(--transition);
}
.faq-trigger:hover { background: var(--surface-2); }
.faq-trigger:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: calc(var(--radius) - 1px);
}
.faq-trigger[aria-expanded="true"] { color: #b8adfd; }

/* ── Chevron icon ─────────────────────────────────────────── */
.faq-icon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  color: var(--text-muted);
  transition: transform var(--transition), color var(--transition);
}
.faq-trigger[aria-expanded="true"] .faq-icon {
  transform: rotate(180deg);
  color: var(--accent);
}

/* ── Answer panel ─────────────────────────────────────────── */
.details {
  overflow: hidden;
  /* height is animated via JS using max-height trick */
  max-height: 0;
  transition: max-height 300ms cubic-bezier(0.4, 0, 0.2, 1);
}
.details[aria-hidden="false"] {
  /* max-height set inline by JS */
}

.details-inner {
  padding: 0 1.4rem 1.3rem;
  color: var(--text-muted);
  font-size: 0.97rem;
  line-height: 1.75;
  border-top: 1px solid var(--border);
  background: var(--answer-bg);
}
.details-inner p + p { margin-top: 0.75rem; }
.details-inner strong { color: var(--text); }
.details-inner a { color: var(--accent); text-decoration: underline; }
.details-inner a:hover { color: #a89ef9; }

/* ── Footer ───────────────────────────────────────────────── */
.site-footer {
  text-align: center;
  padding: 1.5rem;
  color: var(--text-muted);
  font-size: 0.875rem;
  border-top: 1px solid var(--border);
}

/* ── Forced colors ────────────────────────────────────────── */
@media (forced-colors: active) {
  .example { border: 2px solid ButtonBorder; }
  .example.is-open { border-color: Highlight; }
  .faq-trigger { color: ButtonText; }
  .faq-trigger[aria-expanded="true"] { color: Highlight; }
  .faq-icon { color: ButtonText; }
  .faq-trigger[aria-expanded="true"] .faq-icon { color: Highlight; }
  .faq-trigger:focus-visible { outline: 2px solid Highlight; box-shadow: none; }
}

/* ── Reflow at 320px ──────────────────────────────────────── */
@media (max-width: 360px) {
  .faq-trigger { font-size: 0.97rem; padding: 0.9rem 1rem; }
  .details-inner { padding: 0 1rem 1rem; }
}
